#!/usr/bin/env python3
# =====================================================================
#  apply_off_hidden.py  —  fences OFF_HIDDEN_20261117 (TD-009) + CRYPTO_ADMIN_20261117 (TD-021)
#  REQUIRES apply_page_visibility.py (PAGE_VISIBILITY_20261117) on v11.8.7.
#
#  TD-009 — strategies switched OFF are hidden:
#   * hidden = mode OFF on the Settings page AND no open position AND no trade
#     today (one answer for every page: GET /api/strategies/visibility).
#     OFF with a position, or a trade today, stays visible. Fail-open: older
#     backend / unreadable config / fleet feed down → nothing hidden.
#   * Dashboard: no rail card (Legacy) / idle chip (Modern) for a hidden
#     strategy; "of N traded today" leaves it out; a remembered focus on it
#     falls back. Its own page is hidden: Levels (LVB_V1) leaves the nav, the
#     mobile tab bar and #/levels lands on the Dashboard.
#   * Trades + Analytics: two or more hidden strategies sit under ONE
#     "Others · n" chip that opens on click (with "All others"); one alone keeps
#     its own chip; "All" still counts their history.
#  TD-021 — Crypto Lab admin-only: CRYPTO_LAB_OPEN_TO_ALL = False in BOTH
#     api_server.py (routes behind the admin gate) and the frontend.
#  No engine / order / trading code touched.
#
#   backend/app/api/strategy_visibility_routes.py   NEW  the route
#   backend/app/api/test_strategy_visibility.py     NEW  TC-OFFH-0001…0007, TC-CRYPTO-0005
#   backend/app/api_server.py                       mount + crypto flag
#   frontend/src/hooks/useStrategyVisibility.js     NEW  one shared 15 s poll
#   frontend/src/hooks/usePageVisibility.js         crypto flag
#   frontend/src/App.jsx, components/StrategyHost.jsx, pages/ModernDashboard.jsx,
#   pages/PaperTrades.jsx, pages/Analytics.jsx
#   frontend/uitest/test_ui_off_hidden.py           NEW  TC-OFFH-0008…0025, TC-CRYPTO-0001…0004
#   frontend/uitest/test_ui_pages.py                TC-PAGES-0015…0017 now expect Crypto admin-only
#
#  Run ONLY this script, outside market hours, AFTER apply_page_visibility.py:
#     cd ~/dev/scalp-app && python3 apply_off_hidden.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
#  UI checks (optional, app closed):  cd frontend && CI=false npm run build &&
#     PYTHONPATH=../backend python3 uitest/test_ui_off_hidden.py && PYTHONPATH=../backend python3 uitest/test_ui_pages.py
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "OFF_HIDDEN_20261117"
ITEMS = json.loads(r'''[{"path": "backend/app/api_server.py", "orig": "a6e8ad781151809bea147ab43c26b1bf7a3fbd3f59708f605372dd210a1f3a95", "new": "fd20102c1167f5f3c45b7fa30540369bcd158b811c21861b4f15c066764a2718", "blob": ""}, {"path": "backend/app/api/strategy_visibility_routes.py", "orig": null, "new": "29f374ee3ebeb68538461743efada0f4066fabf8c0e610ff491f2b17b3ac3fb9", "blob": ""}, {"path": "backend/app/api/test_strategy_visibility.py", "orig": null, "new": "52225a2c1edf69b24797c04ecb0a509bbccfa5abc37208f4bde87f14b179769f", "blob": ""}, {"path": "frontend/src/hooks/useStrategyVisibility.js", "orig": null, "new": "1593da5f30656ed57380dbd26ff7a5aae28b9fa759226487ba851fbd7d99ce97", "blob": ""}, {"path": "frontend/src/hooks/usePageVisibility.js", "orig": "8d661e38b31f0ad8a79ed55af8588b5d52a19e3501d6960dc005ecaaedc7d8c1", "new": "01be7c30a5bfb4d5e64e29cea6448cd4f7a40c87a85f9ad87c25d2bb8eeb7aba", "blob": ""}, {"path": "frontend/src/App.jsx", "orig": "f6c826b20ebea81d5f9a4f5d5305dd7e2446fe32b7508f3d539fd6e9e4ebffe4", "new": "2fab5c515472fc7609ec24a1910421cbf07e3ced0e0a260e3e9013d057aaffdf", "blob": ""}, {"path": "frontend/src/components/StrategyHost.jsx", "orig": "e7ff346b0d9b5db55c515e2a9b01db2362444d84da6eedc0be64c78c836f3bae", "new": "392b6cba21694a2d750ca6baf76dc17aa51cb4b797a4fc4fd82bb49e481e6123", "blob": ""}, {"path": "frontend/src/pages/ModernDashboard.jsx", "orig": "02f3321d01458a64fbe8c292dd5cdccd41e8b8a1b0b41e012de41161e91ce8bf", "new": "4688650a834eec5fec9d09900a56dfb7271dd833975928329c634c584b06a340", "blob": ""}, {"path": "frontend/src/pages/PaperTrades.jsx", "orig": "8370a7b80a20487652ccffa79c070ff965d28b6f603de773319bd9c200a6e945", "new": "dc86d2016c96f5e6949d728886f600ebd3fa50e3670c71cabb0036d2a60f059d", "blob": ""}, {"path": "frontend/src/pages/Analytics.jsx", "orig": "a85379afc63de683246748c305842a04a32ca9e4e70d2eac60161563246c3639", "new": "1782b3285ab7aa13043e96092ede51ac46b25ef132eb5137d10d327283d89a67", "blob": ""}, {"path": "frontend/uitest/test_ui_pages.py", "orig": "a1c3224d5bb8472c7a4ca72e0386fe45eaa7464065af9aeff8448f107af37b36", "new": "0feb2d5ae562882fa908e2d91a4428a78b67d92371ff09dd0d7bb6946afa575c", "blob": ""}, {"path": "frontend/uitest/test_ui_off_hidden.py", "orig": null, "new": "b9221582494232af226fa91cf97f0c3d0deaf484b8119add9a04f920d9cc075d", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/api/test_strategy_visibility.py", "app/api/test_app_settings_pages.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: PAGE_VISIBILITY_20261117
if "--rollback" not in args:
    _pf = os.path.join(repo, "frontend", "src", "App.jsx")
    if not os.path.exists(_pf) or "PAGE_VISIBILITY_20261117" not in open(_pf, encoding="utf-8").read():
        die("run apply_page_visibility.py first — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # apply_page_visibility.py's own output is expected to be uncommitted still: every planned
        # file was just proven byte-identical to it (sha == orig), so only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="off_hidden_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_off_hidden.py --rollback")
